//! ISO 8601 interval strings: `new DateInterval('P1Y2M3DT4H5M6S')`, `new DatePeriod('R4/2012-07-01T00:00:00Z/P7D')`
//! (port of `PHPSRC/ext/date/lib/parse_iso_intervals.re`).
//!
//! As for the `strtotime()` parser, the scanner (`scanner`) is generated by re2rust 4.1 from a copy of the
//! upstream re2c file whose definitions and rules are verbatim and whose C actions are translated to Rust
//! (`tools/gen_iso_scanner_re.py`, `tools/iso_scanner_rules.re.rs`, `tools/regen_scanner.sh`).

use crate::parse_date::{at, get_nr};
use crate::types::{
    ErrorContainer, ErrorMessage, MAX_ERRORS, RelTime, Time, UNSET, ZONETYPE_OFFSET,
};

// Generated by re2rust: keep it byte-identical to the generator output.
#[rustfmt::skip]
mod scanner;

pub(crate) const EOI: i32 = 257;
pub(crate) const TIMELIB_PERIOD: i32 = 260;
pub(crate) const TIMELIB_ISO_DATE: i32 = 261;

/// `struct _Scanner` of `parse_iso_intervals.re` (the fields the port needs).
pub(crate) struct Scanner {
    /// The trimmed input followed by `YYMAXFILL` NUL bytes.
    pub(crate) str: Vec<u8>,
    /// `YYLIMIT`.
    pub(crate) lim: usize,
    /// Where the next token starts.
    pub(crate) cur: usize,
    /// Start of the current token (`NULL` before the first one).
    pub(crate) tok: Option<usize>,
    pub(crate) errors: ErrorContainer,
    pub(crate) begin: Time,
    pub(crate) end: Time,
    pub(crate) period: RelTime,
    pub(crate) recurrences: i32,
    pub(crate) have_period: bool,
    pub(crate) have_recurrences: bool,
    pub(crate) have_date: bool,
    pub(crate) have_begin_date: bool,
    pub(crate) have_end_date: bool,
}

impl Scanner {
    /// `add_error()` of `parse_iso_intervals.re`. Unlike `parse_date.re`'s, it does not set an error code (the C
    /// field is left uninitialised); the port stores 0.
    pub(crate) fn add_error(&mut self, error: &'static str) {
        if self.errors.error_messages.len() >= MAX_ERRORS {
            return;
        }
        let (position, character) = match self.tok {
            Some(t) => (t as i32, at(&self.str, t)),
            None => (0, 0),
        };
        self.errors.error_messages.push(ErrorMessage {
            error_code: 0,
            position,
            character,
            message: error,
        });
    }

    /// `timelib_string()`: a NUL-terminated copy of the current token `[tok, cur)`.
    pub(crate) fn token(&self) -> Vec<u8> {
        let tok = self.tok.unwrap_or(0);
        let mut v = self.str[tok..self.cur].to_vec();
        v.push(0);
        v
    }
}

/// `timelib_get_unsigned_nr()` (PHPSRC/ext/date/lib/parse_iso_intervals.re): skips to a digit or sign, folds the
/// signs into a direction and multiplies it with the number, all in `timelib_ull` (modular) arithmetic.
/// `TIMELIB_UNSET` comes back as its two's complement when no number is found.
pub(crate) fn get_unsigned_nr(b: &[u8], ptr: &mut usize, max_length: i32) -> u64 {
    let mut dir: u64 = 1;

    while !at(b, *ptr).is_ascii_digit() && at(b, *ptr) != b'+' && at(b, *ptr) != b'-' {
        if at(b, *ptr) == 0 {
            return UNSET as u64;
        }
        *ptr += 1;
    }

    while at(b, *ptr) == b'+' || at(b, *ptr) == b'-' {
        if at(b, *ptr) == b'-' {
            dir = dir.wrapping_mul(u64::MAX);
        }
        *ptr += 1;
    }
    // `timelib_get_nr()` of parse_iso_intervals.re is identical to parse_date.re's.
    dir.wrapping_mul(get_nr(b, ptr, max_length) as u64)
}

/// What `timelib_strtointerval()` returns through its out-parameters.
#[derive(Clone, Debug, PartialEq)]
pub struct IsoInterval {
    /// Start date (`*begin`), set when a date was found before any period.
    pub begin: Option<Time>,
    /// End date (`*end`), set when a date was found after a date or period.
    pub end: Option<Time>,
    /// The duration (`*period`).
    pub period: Option<RelTime>,
    /// `*recurrences`, only written when an `R<n>` part was found.
    pub recurrences: Option<i32>,
    /// Errors (this parser records no warnings).
    pub errors: ErrorContainer,
}

/// The initial `in.begin` / `in.end` of `timelib_strtointerval()`.
fn unset_date() -> Time {
    let mut t = Time::new();
    t.y = UNSET;
    t.d = UNSET;
    t.m = UNSET;
    t.h = UNSET;
    t.i = UNSET;
    t.s = UNSET;
    t.us = 0;
    t.z = 0;
    t.dst = 0;
    t.is_localtime = 0;
    t.zone_type = ZONETYPE_OFFSET;
    t
}

/// C `isspace()` in the C/C.UTF-8 locale.
fn is_c_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Port of `timelib_strtointerval()` (PHPSRC/ext/date/lib/parse_iso_intervals.re): parses an ISO 8601 duration
/// (`P1Y2M3DT4H5M6S`, `P0001-02-03T04:05:06`), date (`20240101T000000Z`, `2024-01-01T00:00:00Z`) and recurrence
/// (`R5`) sequence.
///
/// PHP: `new DateInterval($s)` throws "Unknown or bad format (%s)" when `errors` is not empty, uses `period`
/// when set, else the difference of `begin` and `end` (after `timelib_update_ts()`), else throws "Failed to
/// parse interval (%s)"; `DatePeriod` uses all four parts.
pub fn strtointerval(input: &[u8]) -> IsoInterval {
    let len = input.len();
    let mut s = 0usize;
    let mut e: isize = len as isize - 1;
    let mut result = IsoInterval {
        begin: None,
        end: None,
        period: None,
        recurrences: None,
        errors: ErrorContainer::default(),
    };

    // Unlike timelib_strtotime(), the leading-space loop stops at the last byte (`s < e`).
    if len > 0 {
        while is_c_space(at(input, s)) && (s as isize) < e {
            s += 1;
        }
        while e >= 0 && is_c_space(at(input, e as usize)) && e > s as isize {
            e -= 1;
        }
    }
    if e - (s as isize) < 0 {
        result.errors.error_messages.push(ErrorMessage {
            error_code: 0,
            position: 0,
            character: 0,
            message: "Empty string",
        });
        return result;
    }
    let e = (e + 1) as usize;

    let mut buf = Vec::with_capacity(e - s + scanner::YYMAXFILL);
    buf.extend_from_slice(&input[s..e]);
    buf.resize(e - s + scanner::YYMAXFILL, 0);
    let lim = buf.len();

    let period = RelTime {
        days: UNSET,
        ..RelTime::default()
    };
    let mut sc = Scanner {
        str: buf,
        lim,
        cur: 0,
        tok: None,
        errors: ErrorContainer::default(),
        begin: unset_date(),
        end: unset_date(),
        period,
        recurrences: 1,
        have_period: false,
        have_recurrences: false,
        have_date: false,
        have_begin_date: false,
        have_end_date: false,
    };

    loop {
        if scanner::scan(&mut sc) == EOI {
            break;
        }
    }

    result.errors = sc.errors;
    if sc.have_begin_date {
        result.begin = Some(sc.begin);
    }
    if sc.have_end_date {
        result.end = Some(sc.end);
    }
    if sc.have_period {
        result.period = Some(sc.period);
    }
    if sc.have_recurrences {
        result.recurrences = Some(sc.recurrences);
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn durations() {
        let r = strtointerval(b"P1Y2M3DT4H5M6S");
        assert!(r.errors.error_messages.is_empty());
        let p = r.period.unwrap();
        assert_eq!(
            (p.y, p.m, p.d, p.h, p.i, p.s, p.days),
            (1, 2, 3, 4, 5, 6, UNSET)
        );
        assert_eq!(strtointerval(b"P2W").period.unwrap().d, 14);
        let p = strtointerval(b"P0001-02-03T04:05:06").period.unwrap();
        assert_eq!((p.y, p.m, p.d, p.h, p.i, p.s), (1, 2, 3, 4, 5, 6));
    }

    #[test]
    fn periods_with_dates() {
        let r = strtointerval(b"R4/2012-07-01T00:00:00Z/P7D");
        assert!(r.errors.error_messages.is_empty());
        assert_eq!(r.recurrences, Some(4));
        let b = r.begin.unwrap();
        assert_eq!((b.y, b.m, b.d, b.h, b.i, b.s), (2012, 7, 1, 0, 0, 0));
        assert_eq!(r.period.unwrap().d, 7);
        assert!(r.end.is_none());
    }

    #[test]
    fn errors() {
        let m = |s: &[u8]| {
            strtointerval(s)
                .errors
                .error_messages
                .iter()
                .map(|m| (m.position, m.message))
                .collect::<Vec<_>>()
        };
        assert_eq!(m(b""), [(0, "Empty string")]);
        assert_eq!(m(b"PT"), [(0, "Missing expected time part")]);
        assert_eq!(m(b"P1234567890123D"), [(0, "Undefined period specifier")]);
        assert_eq!(
            m(b"P1X"),
            [
                (0, "Missing expected time part"),
                (1, "Unexpected character"),
                (2, "Unexpected character")
            ]
        );
        assert_eq!(m(b"xP1D"), [(0, "Unexpected character")]);
        // Only the last byte of an all-space string survives the trimming: no error, nothing found.
        let r = strtointerval(b"   ");
        assert!(r.errors.error_messages.is_empty() && r.period.is_none());
    }
}
